package com.snowread.app;

import org.json.*;
import java.io.IOException;
import java.util.*;

/** Optional v3 fields. Strict validation is shared by local loading and ZIP restore. */
final class BookExtras {
    static Typeset typeset(JSONObject j)throws Exception{if(j==null)return null;Typeset t=new Typeset();t.customFont=j.optString("customFont","");t.font=j.optInt("font",21);t.spacing=(float)j.optDouble("spacing",1.65);t.margin=j.optInt("margin",26);t.palette=j.optInt("palette",0);t.fontFamily=j.optInt("fontFamily",0);t.paragraphGap=j.optInt("paragraphGap",0);t.awake=j.optBoolean("awake",false);t.justify=j.optBoolean("justify",false);t.indent=j.optBoolean("indent",false);if(!t.valid())throw new IOException("书籍排版记录无效");return t;}
    static JSONObject json(Typeset t)throws Exception{return new JSONObject().put("customFont",t.customFont).put("font",t.font).put("spacing",t.spacing).put("margin",t.margin).put("palette",t.palette).put("fontFamily",t.fontFamily).put("paragraphGap",t.paragraphGap).put("awake",t.awake).put("justify",t.justify).put("indent",t.indent);}
    static ReadingAnchor anchor(JSONObject j)throws Exception{if(j==null)return null;String chapter=j.getString("chapter"),volume=j.optString("volume",""),context=j.optString("context","");int occurrence=j.optInt("occurrence",0),inside=j.optInt("contextOffset",0),offset=j.getInt("offset"),length=j.getInt("length");double ratio=j.getDouble("ratio"),whole=j.getDouble("wholeRatio");if(chapter.length()>4096||volume.length()>4096||context.length()>256||inside<0||inside>context.length()||occurrence<0||offset<0||length<1||offset>=length||Double.isNaN(ratio)||Double.isNaN(whole)||ratio<0||ratio>1||whole<0||whole>1)throw new IOException("阅读锚点无效");return new ReadingAnchor(chapter,volume,occurrence,context,inside,offset,length,ratio,whole);}
    static JSONObject json(ReadingAnchor a)throws Exception{return new JSONObject().put("chapter",a.chapter).put("volume",a.volume).put("context",a.context).put("contextOffset",a.contextOffset).put("occurrence",a.occurrence).put("offset",a.offset).put("length",a.length).put("ratio",a.ratio).put("wholeRatio",a.wholeRatio);}
    static BookNote annotation(JSONObject j,int length)throws Exception{
        BookNote n=new BookNote(j.getString("id"),j.getInt("start"),j.getInt("end"),j.getString("quote"),j.optString("note",""),j.optInt("style",0),j.getLong("created"),anchor(j.getJSONObject("beginAnchor")),anchor(j.getJSONObject("endAnchor")));
        if(!n.valid(length))throw new IOException("笔记记录无效");return n;
    }
    static JSONObject json(BookNote n)throws Exception{return new JSONObject().put("id",n.id).put("start",n.start).put("end",n.end).put("quote",n.quote).put("note",n.note).put("style",n.style).put("created",n.created).put("beginAnchor",json(n.beginAnchor)).put("endAnchor",json(n.endAnchor));}
    static void read(LibraryStore.Book b,JSONObject j)throws Exception{
        if(j.has("annotations")&&j.optJSONArray("annotations")==null)throw new IOException("笔记列表无效");
        JSONArray annotations=j.optJSONArray("annotations");if(annotations!=null){if(annotations.length()>BookNote.MAX_COUNT)throw new IOException("笔记过多");HashSet<String> ids=new HashSet<>();for(int i=0;i<annotations.length();i++){BookNote n=annotation(annotations.getJSONObject(i),b.length);if(!ids.add(n.id))throw new IOException("笔记标识重复");b.annotations.add(n);}}
        if(j.has("typeset")&&j.optJSONObject("typeset")==null)throw new IOException("排版字段无效");b.typeset=typeset(j.optJSONObject("typeset"));
        b.sourceName=j.optString("sourceName","");b.encodingConfidence=j.optString("encodingConfidence","");if(b.sourceName.length()>4096||b.encodingConfidence.length()>40)throw new IOException("导入来源记录过长");
        if(j.has("anchor")&&j.optJSONObject("anchor")==null||j.has("markAnchors")&&j.optJSONObject("markAnchors")==null||j.has("unmappedMarks")&&j.optJSONArray("unmappedMarks")==null)throw new IOException("阅读位置字段无效");HashSet<Integer> markPositions=new HashSet<>(b.marks);b.anchor=anchor(j.optJSONObject("anchor"));JSONObject anchors=j.optJSONObject("markAnchors");if(anchors!=null)for(Iterator<String> it=anchors.keys();it.hasNext();){String key=it.next();int offset=Integer.parseInt(key);if(!markPositions.contains(offset))throw new IOException("书签锚点关联无效");b.markAnchors.put(offset,anchor(anchors.getJSONObject(key)));}
        JSONArray missing=j.optJSONArray("unmappedMarks");if(missing!=null){if(missing.length()>100000)throw new IOException("未定位书签过多");for(int i=0;i<missing.length();i++){JSONObject item=missing.getJSONObject(i);String note=item.optString("note","");if(note.length()>4000)throw new IOException("书签备注过长");b.unmappedMarks.add(new ReadingAnchor.Unmapped(anchor(item.getJSONObject("anchor")),note));}}
    }
    static void write(LibraryStore.Book b,JSONObject j)throws Exception{JSONArray annotations=new JSONArray();if(b.annotations.size()>BookNote.MAX_COUNT)throw new IOException("笔记过多");HashSet<String> ids=new HashSet<>();for(BookNote n:b.annotations){if(!n.valid(b.length)||!ids.add(n.id))throw new IOException("笔记记录无效");annotations.put(json(n));}if(annotations.length()>0)j.put("annotations",annotations);HashSet<Integer> markPositions=new HashSet<>(b.marks);if(b.typeset!=null)j.put("typeset",json(b.typeset));if(!b.sourceName.isEmpty())j.put("sourceName",b.sourceName);if(!b.encodingConfidence.isEmpty())j.put("encodingConfidence",b.encodingConfidence);if(b.anchor!=null)j.put("anchor",json(b.anchor));JSONObject anchors=new JSONObject();for(Map.Entry<Integer,ReadingAnchor> e:b.markAnchors.entrySet())if(markPositions.contains(e.getKey()))anchors.put(e.getKey().toString(),json(e.getValue()));if(anchors.length()>0)j.put("markAnchors",anchors);JSONArray missing=new JSONArray();for(ReadingAnchor.Unmapped m:b.unmappedMarks)missing.put(new JSONObject().put("anchor",json(m.anchor)).put("note",m.note));if(missing.length()>0)j.put("unmappedMarks",missing);}
    static void copy(LibraryStore.Book from,LibraryStore.Book to){to.annotations.clear();to.annotations.addAll(from.annotations);to.typeset=from.typeset==null?null:from.typeset.copy();to.anchor=from.anchor;to.markAnchors.putAll(from.markAnchors);to.unmappedMarks.addAll(from.unmappedMarks);to.sourceName=from.sourceName;to.encodingConfidence=from.encodingConfidence;}
}
